import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_OW": 32},
        ),
    ],
    key=["OW"],
)
@triton.jit
def avg_pool3d_kernel(
    x_ptr,
    out_ptr,
    C,
    D,
    H,
    W,
    OD,
    OH,
    OW,
    stride_xn,
    stride_xc,
    stride_xd,
    stride_xh,
    stride_on,
    stride_oc,
    stride_od,
    stride_oh,
    KERNEL_SIZE: tl.constexpr,
    STRIDE: tl.constexpr,
    PADDING: tl.constexpr,
    BLOCK_OW: tl.constexpr,
):
    pid_ow = tl.program_id(0)
    pid_ncdoh = tl.program_id(1)

    oh = pid_ncdoh % OH
    tmp = pid_ncdoh // OH
    od = tmp % OD
    tmp2 = tmp // OD
    c = tmp2 % C
    n = tmp2 // C

    ow_start = pid_ow * BLOCK_OW
    ow_offsets = ow_start + tl.arange(0, BLOCK_OW)
    mask_ow = ow_offsets < OW

    base_x = x_ptr + n.to(tl.int64) * stride_xn + c.to(tl.int64) * stride_xc

    acc = tl.zeros((BLOCK_OW,), dtype=tl.float32)

    for kd in range(KERNEL_SIZE):
        d_in = od * STRIDE + kd - PADDING
        d_valid = (d_in >= 0) & (d_in < D)
        if d_valid:
            for kh in range(KERNEL_SIZE):
                h_in = oh * STRIDE + kh - PADDING
                h_valid = (h_in >= 0) & (h_in < H)
                if h_valid:
                    row_base = (
                        base_x
                        + d_in.to(tl.int64) * stride_xd
                        + h_in.to(tl.int64) * stride_xh
                    )
                    for kw in range(KERNEL_SIZE):
                        w_in = ow_offsets * STRIDE + kw - PADDING
                        w_valid = (w_in >= 0) & (w_in < W)
                        mask = mask_ow & w_valid
                        ptrs = row_base + w_in
                        vals = tl.load(ptrs, mask=mask, other=0.0)
                        acc += vals.to(tl.float32)

    inv_count = 1.0 / (KERNEL_SIZE * KERNEL_SIZE * KERNEL_SIZE)
    acc = acc * inv_count

    out_base = (
        out_ptr
        + n.to(tl.int64) * stride_on
        + c.to(tl.int64) * stride_oc
        + od.to(tl.int64) * stride_od
        + oh.to(tl.int64) * stride_oh
    )
    tl.store(out_base + ow_offsets, acc.to(tl.bfloat16), mask=mask_ow)


class Model(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0):
        super(Model, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, D, H, W = x.shape
        OD = (D + 2 * self.padding - self.kernel_size) // self.stride + 1
        OH = (H + 2 * self.padding - self.kernel_size) // self.stride + 1
        OW = (W + 2 * self.padding - self.kernel_size) // self.stride + 1

        output = torch.empty(N, C, OD, OH, OW, device=x.device, dtype=x.dtype)

        grid = lambda META: (
            triton.cdiv(OW, META["BLOCK_OW"]),
            N * C * OD * OH,
        )

        avg_pool3d_kernel[grid](
            x,
            output,
            C,
            D,
            H,
            W,
            OD,
            OH,
            OW,
            x.stride(0),
            x.stride(1),
            x.stride(2),
            x.stride(3),
            output.stride(0),
            output.stride(1),
            output.stride(2),
            output.stride(3),
            KERNEL_SIZE=self.kernel_size,
            STRIDE=self.stride,
            PADDING=self.padding,
        )

        return output


batch_size = 16
channels = 32
depth = 128
height = 128
width = 256
kernel_size = 3
stride = 2
padding = 1


def get_inputs():
    x = torch.rand(batch_size, channels, depth, height, width, dtype=torch.bfloat16)
    return [x]


def get_init_inputs():
    return [kernel_size, stride, padding]
